#!/usr/bin/env python3
"""
extract_cities.py

Reads a Telegram export JSON file and ranks Iranian cities by how many
messages mention them, out of the total number of messages. This is a
message-coverage measure, not a raw word count -- e.g. if 60 out of
100 messages mention a city, that city's score is 60%.

Usage:
    python3 extract_cities.py messages.json
    python3 extract_cities.py messages.json --out cities.csv
"""

