# Manually-added places that fall below the "official city" threshold
# in the source dataset, but are worth catching anyway (e.g. because
# they showed up in real message data). Add to this set as you find
# more -- it's kept separate from ALL_CITIES so it's easy to see/edit.
EXTRA_PLACES = {
    "فشافویه",   # Fashafuyeh -- town SW of Tehran, near Imam Khomeini Airport
    "حسن‌آباد",  # Hasanabad -- common town name near Tehran/Qom
}

ALL_PLACES = ALL_CITIES | EXTRA_PLACES
# -------------------------------------------------------------------------

WORD_PATTERN = re.compile(r"[\w\u200c]+", re.UNICODE)

# Simple regex for filtering messages that contain the phrase
# "پیام های دریافتی" ("received messages"). Matching on the raw text
# is enough here since it's a fixed phrase, not a pattern with variants.
RECEIVED_MESSAGES_PATTERN = re.compile(r"پیام های دریافتی")


def extract_text_from_message(message: dict) -> str:
    text_field = message.get("text")

    if isinstance(text_field, str):
        return text_field

    if isinstance(text_field, list):
        parts = []
        for item in text_field:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                parts.append(item.get("text", ""))
        return "".join(parts)

    entities = message.get("text_entities")
    if isinstance(entities, list):
        parts = [e.get("text", "") for e in entities if isinstance(e, dict)]
        return "".join(parts)

    return ""


def filter_received_messages(messages: list) -> list:
    """
    Keeps only messages whose text contains "پیام های دریافتی".
    Non-dict entries and messages with no text are dropped.
    """
    kept = []
    for message in messages:
        if not isinstance(message, dict):
            continue
        text = extract_text_from_message(message)
        if text and RECEIVED_MESSAGES_PATTERN.search(text):
            kept.append(message)
    return kept


def load_messages(path: str) -> list:
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, dict) and "messages" in data:
        return data["messages"]
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        return [data]

    raise ValueError(
        "Unrecognized JSON structure: expected a Telegram export dict, "
        "a list of messages, or a single message object."
    )


def count_city_messages(messages: list, cities: set):
    """
    For each message, checks which cities are mentioned (as whole words)
    and counts one "hit" per city per message. Returns:
      total_messages: total number of type="message" entries scanned
      city_message_counts: Counter of {city: number of messages mentioning it}
    """
    total_messages = 0
    city_message_counts = Counter()


    for message in messages:

        if not isinstance(message, dict):
            continue
        if message.get("type") != "message":
            continue
        
        total_messages += 1

        text = extract_text_from_message(message)
        if not text:
            continue

        words = set(WORD_PATTERN.findall(text))
        mentioned = words & cities

        for city in mentioned:
            city_message_counts[city] += 1

    return total_messages, city_message_counts


def print_ranking(total_messages: int, city_message_counts: Counter, top: int = None):
    ranked = city_message_counts.most_common(top)
    if not ranked:
        print("No city names found.")
        return

    for i, (city, count) in enumerate(ranked, start=1):
        pct = (count / total_messages * 100) if total_messages else 0
        print(f"{i}. {city} — {count}/{total_messages} messages ({pct:.1f}%)")


def write_csv(total_messages: int, city_message_counts: Counter, out_path: str, top: int = None):
    ranked = city_message_counts.most_common(top)
    with open(out_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["rank", "city", "messages_mentioning", "total_messages", "pct_of_messages"])
        for i, (city, count) in enumerate(ranked, start=1):
            pct = (count / total_messages * 100) if total_messages else 0
            writer.writerow([i, city, count, total_messages, f"{pct:.1f}"])
    print(f"\nSaved {len(ranked)} rows to {out_path}")


def main():
    parser = argparse.ArgumentParser(description="Rank Iranian cities by message coverage.")
    parser.add_argument("json_file")
    parser.add_argument("--top", type=int, default=None)
    parser.add_argument("--out", type=str, default=None)
    args = parser.parse_args()

    try:
        messages = load_messages(args.json_file)
    except FileNotFoundError:
        print(f"Error: file not found: {args.json_file}", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: invalid JSON in {args.json_file}: {e}", file=sys.stderr)
        sys.exit(1)

    total_messages, city_message_counts = count_city_messages(messages, ALL_PLACES)
    messages_with_city = sum(1 for m in messages if isinstance(m, dict) and m.get("type") == "message"
                              and set(WORD_PATTERN.findall(extract_text_from_message(m))) & ALL_PLACES)

    print(f"Total messages: {total_messages}")
    print(f"Messages mentioning at least one city: {messages_with_city}\n")

    print_ranking(total_messages, city_message_counts, top=args.top)

    if args.out:
        write_csv(total_messages, city_message_counts, args.out, top=args.top)


if __name__ == "__main__":
    main()